"use client";

import type { Locale } from "@/lib/i18n/types";

interface Props {
  locale: Locale;
}

/**
 * Browser-side print trigger. Uses the page's print stylesheet (Tailwind's
 * `print:` utilities) for a clean A4 layout. PDF is generated by the user's
 * print-to-PDF — no server PDF renderer needed.
 */
export function ConsultationPrint({ locale }: Props) {
  const isZh = locale === "zh-Hant";
  return (
    <button
      type="button"
      onClick={() => window.print()}
      className="rounded-md border border-border bg-background px-3 py-2 text-sm hover:bg-surface"
    >
      🖨 {isZh ? "列印 / 匯出 PDF" : "Print / Export PDF"}
    </button>
  );
}
